import {ProgramBuilder,instruction,compileProgramModuleParts,stageImage,stageTween,richPage,richText,branchExpression,expr,variable} from 'galbox-sdk/port-kit';
import {bool,parseProgramModule} from 'galbox-sdk/protocol';
import {inspectResource} from 'galbox-sdk/release';
import {createHash} from 'node:crypto';
export const pixel=new TextEncoder().encode('<svg xmlns="http://www.w3.org/2000/svg" width="1" height="1"><path fill="#fdc" d="M0 0h1v1H0z"/></svg>');
export async function liveScopes(holdAll=false,count=72){
 const b=new ProgramBuilder({gameId:'original-live-scopes',release:'v1',entry:'main'}),image=b.asset('image',{id:'pixel',path:'pixel.svg',mime:'image/svg+xml',sha256:createHash('sha256').update(pixel).digest('hex')});b.global({id:'reentry',kind:'bool',initial:bool(false)});
 b.function({id:'main',entry:'intro',layout:1,params:[],locals:[],returns:'void',code:[instruction('text.page',{at:'intro',textId:'intro',revision:'v1',speaker:'Keeper',content:'A long lighthouse shift visits many rooms.'}),...Array.from({length:holdAll?count:1},(_,n)=>stageImage('put'+n,'lamp'+n,image,{x:0})),...Array.from({length:count},(_,n)=>instruction('control.call',{at:'call'+n,function:'chapter'+n,args:[]})),instruction('value.set',{at:'reentry-flag',dest:'reentry',value:{literal:bool(true)}}),instruction('control.call',{at:'reentry-call',function:'chapter1',args:[]}),instruction('text.page',{at:'done',textId:'done',revision:'v1',speaker:'Keeper',content:'Every room returned safely.'}),instruction('control.end',{at:'end'})]});
 for(let n=0;n<count;n++){const at='chapter'+n,code=[...(holdAll||n===0?[stageTween(at+':motion','motion'+n,'lamp'+(holdAll?n:0),{x:100},{duration:10000})]:[]),...(n===1?[branchExpression(at+':branch',expr.variable(variable('reentry','bool')),at+':text',at+':return'),instruction('text.page',{at:at+':text',textId:'reentered',revision:'v1',speaker:'Keeper',content:'The earlier room was entered again.'})]:n===2&&!holdAll?[richPage(at+':history','earlier','v1','Keeper',[richText.text('The earlier room remains in history.')])]:[]),instruction('control.return',{at:at+':return'})];b.function({id:at,entry:code[0]!.at,layout:1,params:[],locals:[],returns:'void',code});}
 const parts=b.parts({compositionVersion:3}),functions=parts.files.flatMap(f=>f.body.functions);parts.files=functions.map((f,n)=>({uri:'code/unit'+n+'.pb',body:parseProgramModule({format:'galbox-code',version:1,id:'unit'+n,functions:[f]})}));const resource=inspectResource({id:'pixel',kind:'image',mime:'image/svg+xml'},pixel,v=>new TextDecoder().decode(v)),built=await compileProgramModuleParts({compositionVersion:3,parts,series:'live-scopes',resources:[resource],packedDeclarations:true});return built;
}
